`#include <stdio.h>

void counter(void) {
    static int c = 0;   /* keeps its value between calls */
    c++;
    printf("%d ", c);
}

int main(void) {
    int a = 7, b = 2;
    printf("%d %d %.2f\n", a / b, a % b, (float)a / b);
    int i = 5;
    int x = i++ + 10;   /* uses 5, then i becomes 6 */
    printf("%d %d\n", x, i);
    char ch = 'A' + 2;
    printf("%c %d\n", ch, ch);
    printf("%d %d\n", -7 / 2, -7 % 2);
    unsigned int u = 0;
    u = u - 1;          /* wraps around */
    printf("%u\n", u);
    int n = 2;
    switch (n) {
        case 1: printf("one ");
        case 2: printf("two ");
        case 3: printf("three "); break;
        default: printf("other");
    }
    printf("\n");
    int arr[] = {10, 20, 30};
    int *p = arr;
    printf("%d %d %d\n", *(p + 1), p[2], (int)(sizeof(arr) / sizeof(arr[0])));
    counter(); counter(); counter();
    printf("\n");
    return 0;
}`

Output:
`3 1 3.50
15 6
C 67
-3 -1
4294967295
two three
20 30 3
1 2 3`

Notes: the `unsigned` wrap-around value assumes a 32-bit `int`, which is true on all common compilers today. `case 2` has no `break`, so control **falls through** into `case 3`. The `static` local variable is initialised only once.

