`import java.util.*;
interface Payment { String pay(int amount); }
class Card implements Payment { public String pay(int a) { return "Card paid " + a; } }
class Upi implements Payment { public String pay(int a) { return "UPI paid " + a; } }
class PaymentFactory {
    static Payment of(String type) {
        switch (type) {
            case "card": return new Card();
            case "upi":  return new Upi();
            default: throw new IllegalArgumentException("unknown " + type);
        }
    }
}
interface Listener { void onEvent(String e); }
class Shop {
    private final List<Listener> listeners = new ArrayList<>();
    void subscribe(Listener l) { listeners.add(l); }
    void checkout(String type, int amount) {
        String r = PaymentFactory.of(type).pay(amount);
        for (Listener l : listeners) l.onEvent(r);
    }
}
public class Main {
    public static void main(String[] args) {
        Shop s = new Shop();
        s.subscribe(e -> System.out.println("Email: " + e));
        s.subscribe(e -> System.out.println("SMS: " + e));
        s.checkout("upi", 499);
        s.checkout("card", 1200);
