`class Node:
    def __init__(self, val, nxt=None):
        self.val, self.next = val, nxt

def build(vals):
    head = None
    for v in reversed(vals):
        head = Node(v, head)
    return head

def to_list(h):
    out = []
    while h:
        out.append(h.val)
        h = h.next
    return out

def reverse(h):
    prev = None
    while h:
        h.next, prev, h = prev, h, h.next
    return prev

def middle(h):
    slow = fast = h
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    return slow.val

def has_cycle(h):
    slow = fast = h
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

def merge(a, b):
    dummy = tail = Node(0)
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b
    return dummy.next

print(to_list(reverse(build([1, 2, 3, 4, 5]))))
print(middle(build([1, 2, 3, 4, 5])))
loop = build([1, 2, 3]); loop.next.next.next = loop
print(has_cycle(loop), has_cycle(build([1, 2])))
print(to_list(merge(build([1, 3, 5]), build([2, 4, 6]))))`

Output:
`[5, 4, 3, 2, 1]
3
True False
[1, 2, 3, 4, 5, 6]`

**Floyd's cycle detection** (tortoise and hare): the fast pointer moves two steps, the slow one step. If there is a loop they must meet inside it; if fast reaches the end, there is no loop.

