def next_greater(a):
    res, st = [-1] * len(a), []      # stack of indices
    for i, x in enumerate(a):
        while st and a[st[-1]] < x:
            res[st.pop()] = x
        st.append(i)
    return res

def eval_postfix(expr):
    st = []
    for tok in expr.split():
        if tok in "+-*/":
            b, a = st.pop(), st.pop()
            st.append({"+": a + b, "-": a - b, "*": a * b, "/": a // b}[tok])
        else:
            st.append(int(tok))
    return st[0]

