`from collections import deque

g = {0: [1, 2], 1: [0, 3], 2: [0, 3], 3: [1, 2, 4], 4: [3]}

def bfs(start):
    dist, order, q = {start: 0}, [], deque([start])
    while q:
        u = q.popleft()
        order.append(u)
        for v in g[u]:
            if v not in dist:
                dist[v] = dist[u] + 1
                q.append(v)
    return order, dist

def dfs(u, seen=None, order=None):
    if seen is None:
        seen, order = set(), []
    seen.add(u); order.append(u)
    for v in g[u]:
        if v not in seen:
            dfs(v, seen, order)
    return order

def topo_sort(n, edges):          # Kahn's algorithm
    adj, indeg = {i: [] for i in range(n)}, [0] * n
    for a, b in edges:
        adj[a].append(b); indeg[b] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    out = []
    while q:
        u = q.popleft(); out.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return out if len(out) == n else "cycle"

