`class Node:
    __slots__ = ('kids', 'end', 'count')
    def __init__(self): self.kids, self.end, self.count = {}, False, 0
class Trie:
    def __init__(self): self.root = Node()
    def insert(self, w):
        n = self.root
        for ch in w:
            n = n.kids.setdefault(ch, Node()); n.count += 1
        n.end = True
    def _walk(self, s):
        n = self.root
        for ch in s:
            n = n.kids.get(ch)
            if n is None: return None
        return n
    def search(self, w):
        n = self._walk(w); return bool(n and n.end)
    def count_prefix(self, p):
        n = self._walk(p); return n.count if n else 0
    def complete(self, p):
        n, out = self._walk(p), []
        def dfs(node, path):
            if node.end: out.append(path)
            for ch in sorted(node.kids): dfs(node.kids[ch], path + ch)
        if n: dfs(n, p)
        return out
