from collections import defaultdict, deque
def dijkstra(g, src):
    dist = {src: 0}; pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]: continue                  # stale entry
        for v, w in g[u]:
