    for u, v in edges: g[u].append(v); indeg[v] += 1
    q, out = deque(i for i in range(n) if indeg[i] == 0), []
    while q:
        u = q.popleft(); out.append(u)
        for v in g[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return out if len(out) == n else 'cycle'
g = {'A': [('B', 4), ('C', 1)], 'B': [('D', 1)], 'C': [('B', 2), ('D', 5)], 'D': []}
print(dijkstra(g, 'A'))
print(kruskal(4, [(1, 0, 1), (3, 1, 2), (4, 2, 3), (2, 0, 2), (5, 1, 3)]))
print(topo(4, [(0, 1), (0, 2), (1, 3), (2, 3)]), topo(3, [(0, 1), (1, 2), (2, 0)]))
d = DSU(5); d.union(0, 1); d.union(3, 4)
print(len({d.find(i) for i in range(5)}), 'components')`

Output:
`{'A': 0, 'B': 3, 'C': 1, 'D': 4}
7
[0, 1, 2, 3] cycle
3 components`

A reaches B more cheaply via C (1 + 2 = 3) than directly (4), and D via B (4). Kruskal picks weights 1, 2 and 4 for an MST of weight 7; edge 3 would close a cycle.

