notes.p:
If you override `equals()` you must override `hashCode()`; otherwise hash-based collections treat equal objects as different:

`import java.util.*;

public class Main {
    static class P1 {
        int x, y;
        P1(int x, int y) { this.x = x; this.y = y; }
    }
    static class P2 {
        int x, y;
        P2(int x, int y) { this.x = x; this.y = y; }
        @Override public boolean equals(Object o) {
            if (!(o instanceof P2)) return false;
            P2 p = (P2) o;
            return x == p.x && y == p.y;
        }
        @Override public int hashCode() { return Objects.hash(x, y); }
    }
    public static void main(String[] args) {
        Set<P1> s1 = new HashSet<>();
        s1.add(new P1(1, 2)); s1.add(new P1(1, 2));
        Set<P2> s2 = new HashSet<>();
        s2.add(new P2(1, 2)); s2.add(new P2(1, 2));
        System.out.println(s1.size() + " " + s2.size());
        try {
            System.out.println(10 / 0);
        } catch (ArithmeticException e) {
            System.out.println("caught " + e.getMessage());
        } finally {
            System.out.println("finally runs");
        }
    }
}`

Output:
`2 1
caught / by zero
finally runs`

