`import json, threading, urllib.request, urllib.error
from http.server import BaseHTTPRequestHandler, HTTPServer
books = {1: {'id': 1, 'title': 'Godaan'}}
class API(BaseHTTPRequestHandler):
    def send(self, code, obj=None):
        body = json.dumps(obj).encode() if obj is not None else b''
        self.send_response(code); self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body))); self.end_headers(); self.wfile.write(body)
    def do_GET(self):
        parts = self.path.strip('/').split('/')
        if parts == ['books']: return self.send(200, list(books.values()))
        if len(parts) == 2 and parts[1].isdigit() and int(parts[1]) in books:
            return self.send(200, books[int(parts[1])])
        self.send(404, {'error': 'not found'})
    def do_POST(self):
        data = json.loads(self.rfile.read(int(self.headers['Content-Length'])))
        if 'title' not in data: return self.send(400, {'error': 'title required'})
        new = {'id': max(books) + 1, 'title': data['title']}; books[new['id']] = new
        self.send(201, new)
    def log_message(self, *a): pass
srv = HTTPServer(('127.0.0.1', 0), API); threading.Thread(target=srv.serve_forever, daemon=True).start()
base = 'http://127.0.0.1:%d' % srv.server_port
def call(method, path, body=None):
    req = urllib.request.Request(base + path, method=method, data=json.dumps(body).encode() if body else None,
                                 headers={'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req) as r: return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e: return e.code, json.loads(e.read())
print(call('POST', '/books', {'title': 'Gitanjali'}))
print(call('POST', '/books', {'name': 'x'}))
print(call('GET', '/books'))
print(call('GET', '/books/99'))
srv.shutdown()`

Output:
`(201, {'id': 2, 'title': 'Gitanjali'})
(400, {'error': 'title required'})
(200, [{'id': 1, 'title': 'Godaan'}, {'id': 2, 'title': 'Gitanjali'}])
(404, {'error': 'not found'})`

Creating returns **201** with the new resource, a malformed body returns **400**, and a missing id returns **404** — the status codes interviewers expect you to pick.
